  isCarried(sessionID) {
    return this.carried.has(sessionID);
  }
  resumedAfterGap(sessionID) {
    const entry = this.sessions.get(sessionID);
    return entry?.afterGap === true && entry.lastProgressAt === undefined;
  }
  knowsEverythingRunning(sessionID) {
    return this.sessions.get(sessionID)?.complete === true;
  }
  lastProgressEventID(sessionID) {
    return this.sessions.get(sessionID)?.lastProgressEventID;
  }
  get(sessionID) {
    const entry = this.sessions.get(sessionID);
    return entry === undefined ? undefined : view(entry);
  }
  *all() {
    for (const [sessionID, entry] of this.sessions) {
      yield [sessionID, view(entry)];
    }
  }
  inExecution(sessionID) {
    const entry = this.sessions.get(sessionID);
    return entry !== undefined && !entry.unended;
  }
  ended(sessionID) {
    return this.executions.get(sessionID)?.ended === true;
  }
  mark(sessionID) {
    return {
      epoch: this.epoch,
      starts: this.executions.get(sessionID)?.starts ?? 0
    };
  }
  sameMark(sessionID, mark) {
    const now = this.mark(sessionID);
    return now.epoch === mark.epoch && now.starts === mark.starts;
  }
  markUnended(sessionID, mark) {
    if (!this.sameMark(sessionID, mark))
      return false;
    const entry = this.sessions.get(sessionID);
    if (entry === undefined)
      return false;
    entry.unended = true;
    entry.responding = false;
    entry.retryAt = undefined;
    entry.tools.clear();
    entry.prompts.clear();
    return true;
  }
  entry(sessionID) {
    const existing = this.sessions.get(sessionID);
    if (existing !== undefined)
      return existing;
    const afterGap = this.carried.delete(sessionID);
    const created = {
      responding: false,
      tools: new Map,
      prompts: new Set,
      unended: false,
      afterGap,
      complete: false
    };
    this.sessions.set(sessionID, created);
    this.bound(this.sessions);
    return created;
  }
  answered(sessionID, key) {
    const entry = this.carried.has(sessionID) ? this.entry(sessionID) : this.sessions.get(sessionID);
    entry?.prompts.delete(key);
  }
  progress(sessionID, event, completes = false) {
    const entry = this.entry(sessionID);
    if (entry.lastProgressAt === undefined || event.created >= entry.lastProgressAt) {
      entry.lastProgressAt = event.created;
      entry.lastProgressEventID = event.id;
    }
    entry.unended = false;
    if (completes)
      entry.complete = true;
    return entry;
  }
  bound(map) {
    while (map.size > MAX_TRACKED_SESSIONS) {
      const oldest = map.keys().next();
      if (oldest.done === true)
        return;
      map.delete(oldest.value);
    }
  }
}
function activityPhase(activity, now) {
