  const idle = info.time.idle;
  if (idle === undefined)
    return;
  const busy = busySince(info);
  return busy !== undefined && idle < busy ? undefined : idle;
}
function view(entry) {
  return {
    ...entry.executionStartedAt === undefined ? {} : { executionStartedAt: entry.executionStartedAt },
    ...entry.responseStartedAt === undefined ? {} : { responseStartedAt: entry.responseStartedAt },
    responding: entry.responding,
    ...entry.lastProgressAt === undefined ? {} : { lastProgressAt: entry.lastProgressAt },
    tools: new Map(entry.tools),
    openPrompts: entry.prompts.size,
    ...entry.retryAt === undefined ? {} : { retryAt: entry.retryAt },
    unended: entry.unended
